  if (v > 1) {
    const p = par[v];
    let a = sets[v], b = sets[p];
    if (a.size > b.size) { const t = a; a = b; b = t; }
    for (const x of a) b.add(x);
    sets[p] = b;
    sets[v] = null;
  }
