import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws IOException {
        StreamTokenizer st = new StreamTokenizer(new BufferedInputStream(System.in));
        st.nextToken();
        int n = (int) st.nval;
        int[] col = new int[n + 1], par = new int[n + 1];
        for (int i = 1; i <= n; i++) { st.nextToken(); col[i] = (int) st.nval; }
        for (int i = 2; i <= n; i++) { st.nextToken(); par[i] = (int) st.nval; }
        @SuppressWarnings("unchecked")
        HashSet<Integer>[] sets = new HashSet[n + 1];
        for (int v = 1; v <= n; v++) { sets[v] = new HashSet<>(); sets[v].add(col[v]); }
        int[] ans = new int[n + 1];
        for (int v = n; v >= 1; v--) {
            ans[v] = sets[v].size();
            if (v > 1) {
                int p = par[v];
                HashSet<Integer> a = sets[v], b = sets[p];
                if (a.size() > b.size()) { HashSet<Integer> t = a; a = b; b = t; }
                b.addAll(a);
                sets[p] = b;
                sets[v] = null;
            }
        }
        StringBuilder sb = new StringBuilder();
        for (int v = 1; v <= n; v++) sb.append(ans[v]).append('\n');
        System.out.print(sb);
    }
}

