#include <bits/stdc++.h>
using namespace std;
int main() {
    int n;
    scanf("%d", &n);
    vector<int> col(n + 1), par(n + 1, 0);
    for (int i = 1; i <= n; i++) scanf("%d", &col[i]);
    for (int i = 2; i <= n; i++) scanf("%d", &par[i]);
    vector<unordered_set<int>> sets(n + 1);
    for (int v = 1; v <= n; v++) sets[v].insert(col[v]);
    vector<int> ans(n + 1, 0);
    for (int v = n; v >= 1; v--) {
        ans[v] = (int)sets[v].size();
        if (v > 1) {
            int p = par[v];
            if (sets[v].size() > sets[p].size()) swap(sets[v], sets[p]);   // swap is O(1); pour the smaller into the larger
            for (int x : sets[v]) sets[p].insert(x);
            sets[v].clear();
        }
    }
    for (int v = 1; v <= n; v++) printf("%d\n", ans[v]);
    return 0;
}
